/*
 * Unit tests for scripts/includes/nm_lyricsalign_phones.h: parsing espeak-ng's
 * IPA output into words and phones, and the five-step mapping of a phone onto
 * the model's vocabulary (nomercy-ffmpeg #126, "Phonemes: espeak-ng").
 *
 * Plain C, no FFmpeg and no espeak-ng:
 *
 *   cc -std=c11 -Wall -Wextra -Werror -I scripts/includes \
 *      tests/unit/test_nm_lyricsalign_phones.c -lm -o test_nm_lyricsalign_phones
 *   NM_UNIT_FIXTURES=tests/unit/fixtures ./test_nm_lyricsalign_phones
 *
 * The fixtures are generated by tools/lyricsalign-lab/make_phone_fixture.py
 * from espeak-ng 1.52.0 and the prototype's mapping rules: every distinct
 * phone of a twelve-voice corpus with the id the prototype maps it to.
 */
#define _POSIX_C_SOURCE 200809L   /* strdup, strtok_r under -std=c11 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "nm_lyricsalign_phones.h"
#include "fixtures/jfk/jfk_fixture.h"

static int failures;
static int checks;

#define CHECK(cond) do {                                                    \
        checks++;                                                           \
        if (!(cond)) {                                                      \
            failures++;                                                     \
            fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
        }                                                                   \
    } while (0)

#define CHECK_EQ_INT(got, want) do {                                               \
        int g_ = (got), w_ = (want);                                               \
        checks++;                                                                  \
        if (g_ != w_) {                                                            \
            failures++;                                                            \
            fprintf(stderr, "FAIL %s:%d: %s = %d, want %d\n", __FILE__, __LINE__, \
                    #got, g_, w_);                                                 \
        }                                                                          \
    } while (0)

/* ------------------------------------------------------------------------ */

static char *read_file(const char *rel)
{
    const char *dir = getenv("NM_UNIT_FIXTURES");
    char path[1024];
    FILE *f;
    long size;
    char *buf;

    if (!dir)
        dir = "tests/unit/fixtures";
    snprintf(path, sizeof(path), "%s/%s", dir, rel);
    f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "cannot open %s\n", path);
        return NULL;
    }
    fseek(f, 0, SEEK_END);
    size = ftell(f);
    fseek(f, 0, SEEK_SET);
    buf = malloc(size + 1);
    if (fread(buf, 1, size, f) != (size_t) size) {
        free(buf);
        fclose(f);
        return NULL;
    }
    buf[size] = 0;
    fclose(f);
    return buf;
}

static char **vocab;
static int n_vocab;

static void load_vocab(void)
{
    char *text = read_file("lyricsalign-vocab.txt");
    char *p;

    CHECK(text != NULL);
    if (!text)
        return;
    vocab = calloc(512, sizeof(*vocab));
    for (p = strtok(text, "\n"); p && n_vocab < 512; p = strtok(NULL, "\n"))
        vocab[n_vocab++] = strdup(p);
    free(text);
    CHECK_EQ_INT(n_vocab, 392);
    CHECK(n_vocab > 0 && !strcmp(vocab[0], "<pad>"));
}

static int id_of(const char *phone)
{
    for (int i = 0; i < n_vocab; i++)
        if (!strcmp(vocab[i], phone))
            return i;
    return -1;
}

/* ------------------------------------------------------------------------ */

static void test_parse_jfk_ipa(void)
{
    char *raw = read_file("jfk/jfk-ipa.txt");
    NMLpWord *words = NULL;
    int n_words = 0, k = 0;

    CHECK(raw != NULL);
    if (!raw)
        return;
    CHECK_EQ_INT(nm_lp_parse_ipa(raw, &words, &n_words), 0);
    CHECK_EQ_INT(n_words, JFK_N_WORDS);
    for (int w = 0; w < n_words && w < JFK_N_WORDS; w++) {
        CHECK_EQ_INT(words[w].n, JFK_WORD_PHONES[w]);
        for (int i = 0; i < words[w].n && k < JFK_N_TOKENS; i++, k++) {
            checks++;
            if (strcmp(words[w].phones[i], JFK_PHONE_STRINGS[k])) {
                failures++;
                fprintf(stderr, "FAIL word %d phone %d: '%s', fixture '%s'\n", w, i, words[w].phones[i],
                        JFK_PHONE_STRINGS[k]);
            }
        }
    }
    CHECK_EQ_INT(k, JFK_N_TOKENS);
    nm_lp_free_words(words, n_words);
    free(raw);
}

static void test_parse_strips_language_switch(void)
{
    NMLpWord *words = NULL;
    int n = 0;

    CHECK_EQ_INT(nm_lp_parse_ipa("(nl)h\xCB\x88\xC9\x9Blo\xCA\x8A_w\xC9\x9C\xCB\x90ld (en-us)x", &words, &n), 0);
    CHECK_EQ_INT(n, 2);
    if (n == 2) {
        CHECK_EQ_INT(words[0].n, 2);
        CHECK(!strcmp(words[0].phones[0], "h\xC9\x9Blo\xCA\x8A"));     /* hɛloʊ, stress dropped */
        CHECK(!strcmp(words[0].phones[1], "w\xC9\x9C\xCB\x90ld"));    /* wɜːld */
        CHECK_EQ_INT(words[1].n, 1);
        CHECK(!strcmp(words[1].phones[0], "x"));
    }
    nm_lp_free_words(words, n);
}

static void test_parse_drops_empty(void)
{
    NMLpWord *words = NULL;
    int n = 0;

    /* an empty phone, a phone of only a stress mark, a word of nothing, trailing blanks */
    CHECK_EQ_INT(nm_lp_parse_ipa("_\xCB\x88_ a__b  \n\t _ \n", &words, &n), 0);
    CHECK_EQ_INT(n, 1);
    if (n == 1) {
        CHECK_EQ_INT(words[0].n, 2);
        CHECK(!strcmp(words[0].phones[0], "a"));
        CHECK(!strcmp(words[0].phones[1], "b"));
    }
    nm_lp_free_words(words, n);

    words = NULL;
    n = 0;
    CHECK_EQ_INT(nm_lp_parse_ipa("", &words, &n), 0);
    CHECK_EQ_INT(n, 0);
    nm_lp_free_words(words, n);
}

static void test_map_fixture_rows(void)
{
    char *text = read_file("lyricsalign-phones.tsv");
    char *line, *save = NULL;
    int rows = 0;

    CHECK(text != NULL);
    if (!text)
        return;
    for (line = strtok_r(text, "\n", &save); line; line = strtok_r(NULL, "\n", &save)) {
        char *tab = strchr(line, '\t');
        int want, got;

        if (line[0] == '#' || !tab)
            continue;
        *tab = 0;
        want = atoi(tab + 1);
        got = nm_lp_map_phone(line, (const char *const *) vocab, n_vocab);
        rows++;
        checks++;
        if (got != want) {
            failures++;
            fprintf(stderr, "FAIL phone '%s': mapped to %d, fixture %d\n", line, got, want);
        }
    }
    CHECK(rows >= 100);
    free(text);
}

static void test_map_chain_order(void)
{
    /* 1. the phone itself */
    CHECK_EQ_INT(nm_lp_map_phone("n", (const char *const *) vocab, n_vocab), id_of("n"));
    CHECK_EQ_INT(nm_lp_map_phone("o\xCA\x8A", (const char *const *) vocab, n_vocab), id_of("o\xCA\x8A"));   /* oʊ */
    /* 2. the table beats NFD: ʌʊ -> aʊ, œy -> ɔø, ʏ -> ʊ */
    CHECK_EQ_INT(nm_lp_map_phone("\xCA\x8C\xCA\x8A", (const char *const *) vocab, n_vocab), id_of("a\xCA\x8A"));
    CHECK_EQ_INT(nm_lp_map_phone("\xC5\x93y", (const char *const *) vocab, n_vocab), id_of("\xC9\x94\xC3\xB8"));
    CHECK_EQ_INT(nm_lp_map_phone("\xCA\x8F", (const char *const *) vocab, n_vocab), id_of("\xCA\x8A"));
    /* 3. combining marks dropped: eɪ̯ -> eɪ. (ɛ̃, by contrast, is in the
     * vocabulary itself and is found at step 1; the fixture says id 69.) */
    CHECK(id_of("e\xC9\xAA\xCC\xAF") < 0 && id_of("e\xC9\xAA") >= 0);
    CHECK_EQ_INT(nm_lp_map_phone("e\xC9\xAA\xCC\xAF", (const char *const *) vocab, n_vocab), id_of("e\xC9\xAA"));
    CHECK(id_of("\xC9\x9B\xCC\x83") >= 0);
    CHECK_EQ_INT(nm_lp_map_phone("\xC9\x9B\xCC\x83", (const char *const *) vocab, n_vocab), id_of("\xC9\x9B\xCC\x83"));
    /* 3, with a precomposed letter: ãː -> aː, which the vocabulary has (so step 4 is not reached) */
    CHECK(id_of("\xC3\xA3\xCB\x90") < 0 && id_of("a\xCB\x90") >= 0);
    CHECK_EQ_INT(nm_lp_map_phone("\xC3\xA3\xCB\x90", (const char *const *) vocab, n_vocab), id_of("a\xCB\x90"));
    /* 4. the length mark dropped after the marks: aɪː -> aɪ (aɪː is not in the vocabulary, aɪ is;
     *    a step-5 answer would be the first code point, a, which is a different id) */
    CHECK(id_of("a\xC9\xAA\xCB\x90") < 0 && id_of("a\xC9\xAA") >= 0 && id_of("a") >= 0);
    CHECK_EQ_INT(nm_lp_map_phone("a\xC9\xAA\xCB\x90", (const char *const *) vocab, n_vocab), id_of("a\xC9\xAA"));
    CHECK(id_of("\xC9\x90\xCB\x90") < 0 && id_of("\xC9\x90") >= 0);
    CHECK_EQ_INT(nm_lp_map_phone("\xC9\x90\xCB\x90", (const char *const *) vocab, n_vocab), id_of("\xC9\x90"));
    /* 5. the first code point: nə -> n (neither nə nor anything shorter but n is in the vocabulary) */
    CHECK(id_of("n\xC9\x99") < 0 && id_of("n") >= 0);
    CHECK_EQ_INT(nm_lp_map_phone("n\xC9\x99", (const char *const *) vocab, n_vocab), id_of("n"));
    /* a miss: ʰ alone, and a lone combining tilde */
    CHECK_EQ_INT(nm_lp_map_phone("\xCA\xB0", (const char *const *) vocab, n_vocab), -1);
    CHECK_EQ_INT(nm_lp_map_phone("\xCC\x83", (const char *const *) vocab, n_vocab), -1);
    CHECK_EQ_INT(nm_lp_map_phone("", (const char *const *) vocab, n_vocab), -1);
}

static void test_strip_marks(void)
{
    char out[64];

    CHECK_EQ_INT(nm_lp_strip_marks("\xC9\x9B\xCC\x83", out, sizeof(out)), 0);
    CHECK(!strcmp(out, "\xC9\x9B"));
    CHECK_EQ_INT(nm_lp_strip_marks("\xC3\xA3\xCB\x90", out, sizeof(out)), 0);
    CHECK(!strcmp(out, "a\xCB\x90"));                                 /* ã -> a, ː kept (it is Lm, not Mn) */
    CHECK_EQ_INT(nm_lp_strip_marks("t\xCC\xAA", out, sizeof(out)), 0);
    CHECK(!strcmp(out, "t"));                                         /* dental t̪ */
    CHECK_EQ_INT(nm_lp_strip_marks("a\xE2\x80\x8B" "b", out, sizeof(out)), 0);
    CHECK(!strcmp(out, "ab"));                                        /* zero-width space (Cf) */
    CHECK_EQ_INT(nm_lp_strip_marks("x", out, 1), -1);                 /* no room */
}

int main(void)
{
    load_vocab();
    test_parse_jfk_ipa();
    test_parse_strips_language_switch();
    test_parse_drops_empty();
    test_map_fixture_rows();
    test_map_chain_order();
    test_strip_marks();
    fprintf(stderr, "%d checks, %d failures\n", checks, failures);
    return failures ? 1 : 0;
}
